import{_ as n,H as a,f as p,i as e}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"07｜百舸争流：多任务并行探索与流水线编排","description":"","frontmatter":{},"headers":[{"level":2,"title":"场景一：新接手一个大型项目","slug":"场景一-新接手一个大型项目","link":"#场景一-新接手一个大型项目","children":[]},{"level":2,"title":"场景二：修复一个复杂的 bug","slug":"场景二-修复一个复杂的-bug","link":"#场景二-修复一个复杂的-bug","children":[]},{"level":2,"title":"项目一：并行探索","slug":"项目一-并行探索","link":"#项目一-并行探索","children":[{"level":3,"title":"并行探索子代理","slug":"并行探索子代理","link":"#并行探索子代理","children":[]},{"level":3,"title":"使用并行探索","slug":"使用并行探索","link":"#使用并行探索","children":[]},{"level":3,"title":"前台与后台运行","slug":"前台与后台运行","link":"#前台与后台运行","children":[]},{"level":3,"title":"并行探索的隐含前提：任务必须真正独立","slug":"并行探索的隐含前提-任务必须真正独立","link":"#并行探索的隐含前提-任务必须真正独立","children":[]}]},{"level":2,"title":"项目二：流水线编排","slug":"项目二-流水线编排","link":"#项目二-流水线编排","children":[{"level":3,"title":"Bug修复流水线","slug":"bug修复流水线","link":"#bug修复流水线","children":[]},{"level":3,"title":"使用流水线","slug":"使用流水线","link":"#使用流水线","children":[]},{"level":3,"title":"流水线的架构约束：子代理不能嵌套","slug":"流水线的架构约束-子代理不能嵌套","link":"#流水线的架构约束-子代理不能嵌套","children":[]},{"level":3,"title":"长流水线的保障：Resume 恢复机制","slug":"长流水线的保障-resume-恢复机制","link":"#长流水线的保障-resume-恢复机制","children":[]}]},{"level":2,"title":"流水线的核心工程问题：阶段间的“交接契约”","slug":"流水线的核心工程问题-阶段间的-交接契约","link":"#流水线的核心工程问题-阶段间的-交接契约","children":[{"level":3,"title":"什么是“交接契约”？","slug":"什么是-交接契约","link":"#什么是-交接契约","children":[]},{"level":3,"title":"在 prompt 中实现交接契约","slug":"在-prompt-中实现交接契约","link":"#在-prompt-中实现交接契约","children":[]}]},{"level":2,"title":"主对话的角色：编排者，而非旁观者","slug":"主对话的角色-编排者-而非旁观者","link":"#主对话的角色-编排者-而非旁观者","children":[{"level":3,"title":"编排者的四种介入形式","slug":"编排者的四种介入形式","link":"#编排者的四种介入形式","children":[]},{"level":3,"title":"编排者的 prompt 设计","slug":"编排者的-prompt-设计","link":"#编排者的-prompt-设计","children":[]}]},{"level":2,"title":"当流水线阶段失败时怎么办？","slug":"当流水线阶段失败时怎么办","link":"#当流水线阶段失败时怎么办","children":[]},{"level":2,"title":"并行 vs 流水线：什么时候用什么","slug":"并行-vs-流水线-什么时候用什么","link":"#并行-vs-流水线-什么时候用什么","children":[{"level":3,"title":"模式一：Fan-out → Fan-in（扇出→聚合）","slug":"模式一-fan-out-→-fan-in-扇出→聚合","link":"#模式一-fan-out-→-fan-in-扇出→聚合","children":[]},{"level":3,"title":"模式二：Pipeline + Parallel Stage（流水线中嵌套并行）","slug":"模式二-pipeline-parallel-stage-流水线中嵌套并行","link":"#模式二-pipeline-parallel-stage-流水线中嵌套并行","children":[]},{"level":3,"title":"模式三：Parallel Pipelines（多条流水线并行）","slug":"模式三-parallel-pipelines-多条流水线并行","link":"#模式三-parallel-pipelines-多条流水线并行","children":[]}]},{"level":2,"title":"本讲小结","slug":"本讲小结","link":"#本讲小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"动手练习","slug":"动手练习","link":"#动手练习","children":[]}],"relativePath":"ClaudeCode工程化实战/07｜百舸争流：多任务并行探索与流水线编排.md","filePath":"ClaudeCode工程化实战/07｜百舸争流：多任务并行探索与流水线编排.md","lastUpdated":1779815462000}'),l={name:"ClaudeCode工程化实战/07｜百舸争流：多任务并行探索与流水线编排.md"};function i(t,s,c,o,r,d){return a(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="_07-百舸争流-多任务并行探索与流水线编排" tabindex="-1">07｜百舸争流：多任务并行探索与流水线编排 <a class="header-anchor" href="#_07-百舸争流-多任务并行探索与流水线编排" aria-label="Permalink to &quot;07｜百舸争流：多任务并行探索与流水线编排&quot;">​</a></h1><p>你好，我是黄佳。</p><p>欢迎来到 Claude Code 工程化实战的第 7 讲。前面我们学习了只读型子代理和高噪声任务处理，今天我们要探索子代理的另外两个强大工程应用场景—— <strong>并行探索</strong> 和 <strong>流水线编排</strong>。</p><p>这两个应用分别解决的问题是什么呢？并行探索,当你需要同时从多个角度理解或处理一件事时启用；流水线编排,当一个复杂任务可以拆成多个连续阶段时启用。</p><p>今天的内容比较多，学习目标包括：</p><ol><li><p>掌握并行探索和流水线编排的基本使用。</p></li><li><p>通过实战项目体验两种模式的差异。</p></li><li><p>理解“独立→并行，依赖→流水线”的判断标准。</p></li><li><p>学会设计阶段间的“交接契约”，确保流水线信息不丢失。</p></li><li><p>掌握混合模式——当一个任务既有并行部分，又有串行部分时如何编排。</p></li><li><p>理解主对话作为“编排者”的角色定位和决策介入点。</p></li></ol><p>我们还是老规矩，从两个真实场景来开始。</p><h2 id="场景一-新接手一个大型项目" tabindex="-1">场景一：新接手一个大型项目 <a class="header-anchor" href="#场景一-新接手一个大型项目" aria-label="Permalink to &quot;场景一：新接手一个大型项目&quot;">​</a></h2><p>你刚加入一个团队，需要快速理解一个包含几十个模块的后端项目。传统方式下，我们可能要花费很久的时间熟悉。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 看 auth 模块 → 花 3 小时</span></span>
<span class="line"><span>2. 看 database 模块 → 花 5 小时</span></span>
<span class="line"><span>3. 看 api 模块 → 花 40 分钟</span></span>
<span class="line"><span>4. 综合理解 → ???</span></span></code></pre></div><p>串行探索既慢，又容易在中途忘记前面看到的细节。</p><p>而并行探索的方式就不一样了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945070/18dcaeeb751005b678e0b9363900d9fb.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945070/18dcaeeb751005b678e0b9363900d9fb.jpg" alt=""></a></p><p>三个子代理 <strong>同时</strong> 工作，各自探索自己的领域，最后汇总成一份综合报告。</p><h2 id="场景二-修复一个复杂的-bug" tabindex="-1">场景二：修复一个复杂的 bug <a class="header-anchor" href="#场景二-修复一个复杂的-bug" aria-label="Permalink to &quot;场景二：修复一个复杂的 bug&quot;">​</a></h2><p>遇到一个“用户登录后偶尔 token 验证失败”的 bug。这种间歇性问题最难调试。</p><p>如果让主对话直接处理，上下文会很快被塞满：</p><ul><li><p>搜索相关代码 → 200 行输出</p></li><li><p>分析可能的原因 → 又是 200 行</p></li><li><p>修复 → 100 行</p></li><li><p>验证 → 又是测试输出……</p></li></ul><p>而流水线的方式，每个阶段只返回 <strong>摘要</strong>，主对话始终保持清洁，可以随时介入做决策。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945070/936b91a3466d6f5ff16964a6e88bb58c.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945070/936b91a3466d6f5ff16964a6e88bb58c.jpg" alt=""></a></p><h2 id="项目一-并行探索" tabindex="-1">项目一：并行探索 <a class="header-anchor" href="#项目一-并行探索" aria-label="Permalink to &quot;项目一：并行探索&quot;">​</a></h2><p>接下来我们直接进入实战演练。</p><h3 id="并行探索子代理" tabindex="-1">并行探索子代理 <a class="header-anchor" href="#并行探索子代理" aria-label="Permalink to &quot;并行探索子代理&quot;">​</a></h3><p>实战项目位于 <code>03-SubAgents/projects/04-parallel-explore/</code>，包含三个专门的探索子代理。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>04-parallel-explore/</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   ├── auth/           # 认证模块</span></span>
<span class="line"><span>│   │   ├── index.js</span></span>
<span class="line"><span>│   │   ├── jwt.js</span></span>
<span class="line"><span>│   │   └── session.js</span></span>
<span class="line"><span>│   ├── database/       # 数据库模块</span></span>
<span class="line"><span>│   │   ├── index.js</span></span>
<span class="line"><span>│   │   ├── models.js</span></span>
<span class="line"><span>│   │   └── migrations.js</span></span>
<span class="line"><span>│   └── api/            # API 模块</span></span>
<span class="line"><span>│       ├── index.js</span></span>
<span class="line"><span>│       ├── routes.js</span></span>
<span class="line"><span>│       └── middleware.js</span></span>
<span class="line"><span>└── .claude/agents/</span></span>
<span class="line"><span>    ├── auth-explorer.md</span></span>
<span class="line"><span>    ├── db-explorer.md</span></span>
<span class="line"><span>    └── api-explorer.md</span></span></code></pre></div><p>auth-explorer子代理的配置如下。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: auth-explorer</span></span>
<span class="line"><span>description: Explore and analyze authentication-related code. Use when investigating auth flows, session management, or security.</span></span>
<span class="line"><span>tools: Read, Grep, Glob</span></span>
<span class="line"><span>model: haiku</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are an authentication specialist focused on exploring auth-related code.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Your Domain</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Focus ONLY on authentication-related concerns:</span></span>
<span class="line"><span>- Login/logout flows</span></span>
<span class="line"><span>- Token generation and validation (JWT, sessions)</span></span>
<span class="line"><span>- Password handling</span></span>
<span class="line"><span>- Permission and role systems</span></span>
<span class="line"><span>- Session management</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## When Invoked</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. **Locate Auth Code**: Use Glob to find auth-related files</span></span>
<span class="line"><span>   - Patterns: \`**/auth/**\`, \`**/*auth*\`, \`**/*login*\`, \`**/*session*\`, \`**/*jwt*\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. **Analyze Structure**: Read key files and understand:</span></span>
<span class="line"><span>   - How users authenticate</span></span>
<span class="line"><span>   - How tokens are generated/validated</span></span>
<span class="line"><span>   - How sessions are managed</span></span>
<span class="line"><span>   - How permissions are checked</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. **Report Findings**</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Output Format</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`markdown</span></span>
<span class="line"><span>## Auth Module Analysis</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Overview</span></span>
<span class="line"><span>[1-2 sentence summary]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Authentication Flow</span></span>
<span class="line"><span>1. [Step 1]</span></span>
<span class="line"><span>2. [Step 2]</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Key Components</span></span>
<span class="line"><span>| Component | File | Purpose |</span></span>
<span class="line"><span>|-----------|------|---------|</span></span>
<span class="line"><span>| ... | ... | ... |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Token Strategy</span></span>
<span class="line"><span>- Type: [JWT/Session/etc]</span></span>
<span class="line"><span>- Expiry: [duration]</span></span>
<span class="line"><span>- Storage: [where stored]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Security Notes</span></span>
<span class="line"><span>- [Observations about security posture]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Guidelines</span></span>
<span class="line"><span>- Stay within auth domain - don&#39;t analyze unrelated code</span></span>
<span class="line"><span>- Note any security concerns you observe</span></span>
<span class="line"><span>- Be concise - main conversation will synthesize</span></span></code></pre></div><p>关键设计点如下：</p><ul><li>tools: <code>Read, Grep, Glob</code>，全部只读，探索不需要修改任何东西，这三个工具足够完成代码探索任务。</li><li>model: <code>haiku</code>，探索任务相对简单，追求速度，haiku更快更便宜。</li><li>Stay within auth domain：明确告诉子代理它的职责边界，防止它越界去分析不相关的代码。</li></ul><p>用同样的模式创建另外两个探索子代理 db-explorer 和 api-explorer，只需要修改：</p><ul><li><p><code>name</code> 和 <code>description</code></p></li><li><p><code>Your Domain</code> 部分的关注点</p></li><li><p><code>Output Format</code> 中的报告结构</p></li></ul><h3 id="使用并行探索" tabindex="-1"><strong>使用并行探索</strong> <a class="header-anchor" href="#使用并行探索" aria-label="Permalink to &quot;**使用并行探索**&quot;">​</a></h3><p>进入项目目录，在 Claude Code 的命令行中输入：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同时让 auth-explorer、db-explorer、api-explorer 探索各自模块， 然后汇总给我一个整体架构理解</span></span></code></pre></div><p>此时 Claude 会完成下述步骤。</p><ol><li><p>并行启动三个子代理</p></li><li><p>各自独立执行探索任务</p></li><li><p>收集三份报告</p></li><li><p>综合成一份整体架构理解</p></li></ol><p>并行执行的价值显而易见。传统情况下，如果不使用子代理并行处理，假设每个模块用时30 秒，串行总耗时90秒，主对话上下文会被三个模块的探索过程塞满；而并行整体用时30秒，且只有三份简洁报告。并行执行不仅更快，而且主对话的上下文更清洁。</p><h3 id="前台与后台运行" tabindex="-1">前台与后台运行 <a class="header-anchor" href="#前台与后台运行" aria-label="Permalink to &quot;前台与后台运行&quot;">​</a></h3><p>在 Claude Code 中，子代理默认在 <strong>前台</strong> 运行——你能看到它实时输出的每一行。并行探索时，如果三个子代理都在前台，你的终端会被占满。</p><p>当一个子代理正在前台运行时，按 <strong><code>Ctrl+B</code> 可以将它切换到后台继续执行</strong>。这在并行场景下非常实用。</p><p>我们梳理一下操作流程。</p><ol><li><p>触发 auth-explorer → 看到它开始搜索</p></li><li><p>按 Ctrl+B → auth-explorer 转入后台</p></li><li><p>触发 db-explorer → 看到它开始搜索</p></li><li><p>按 Ctrl+B → db-explorer 转入后台</p></li><li><p>触发 api-explorer → 看到它开始搜索</p></li><li><p>按 Ctrl+B → api-explorer 转入后台（或留在前台观察）</p></li><li><p>三个子代理在后台同时执行，完成后返回结果</p></li></ol><p>后台运行的一个重要限制是 <strong>无法弹出权限确认对话框</strong>。所以如果子代理需要执行 Bash 命令等需要审批的操作，要么提前用 <code>permissionMode: bypassPermissions</code> 授权（仅限可信场景），要么让它留在前台。对于我们的只读探索子代理（tools 只有 Read/Grep/Glob），不需要权限审批，所以切到后台完全没问题。</p><h3 id="并行探索的隐含前提-任务必须真正独立" tabindex="-1">并行探索的隐含前提：任务必须真正独立 <a class="header-anchor" href="#并行探索的隐含前提-任务必须真正独立" aria-label="Permalink to &quot;并行探索的隐含前提：任务必须真正独立&quot;">​</a></h3><p>并行看起来很美好，但有一个容易被忽略的前提：各子代理的探索任务之间不能有信息依赖。</p><p>什么叫有信息依赖？我们拿一个电商项目举例。</p><ul><li><p>auth-explorer 发现用户认证使用 JWT，token 中包含 userId 和 role 。</p></li><li><p>db-explorer发现 users 表有 role 字段，但 orders 表里也有 user_role 冗余字段 。</p></li><li><p>api-explorer: 发现 /admin/* 路由用了中间件检查 role。</p></li></ul><p>问题来了！这三个发现之间有关联——role 的传递路径横跨三个模块，但因为并行执行，每个子代理都不知道其他两个发现了什么！这不是 bug，而是设计约束。并行探索的综合分析必须由主对话来完成。子代理负责“收集原始情报”，主对话负责“连点成线”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945070/29158b9e4c263abd13a6cac88500961f.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945070/29158b9e4c263abd13a6cac88500961f.jpg" alt=""></a></p><p>在这个场景中，因为主对话可以进行汇总，因此整体分析结果仍然可行，但在有些情况下，各任务间强相互依赖时，就必须等待。</p><p>那么，如何判断是否适合并行，检查清单如下：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每个子任务能否独立完成，不需要另一个子任务的结果？</span></span>
<span class="line"><span>是 → 可以并行</span></span>
<span class="line"><span>否 → 必须串行或混合模式</span></span>
<span class="line"><span></span></span>
<span class="line"><span>遗漏跨模块关联是否可接受？</span></span>
<span class="line"><span>是（主对话会综合分析）→ 可以并行</span></span>
<span class="line"><span>否（遗漏可能导致错误决策）→ 考虑串行或增加综合分析阶段</span></span>
<span class="line"><span></span></span>
<span class="line"><span>子任务的输出粒度是否匹配？</span></span>
<span class="line"><span>是（都是模块级概览）→ 容易综合</span></span>
<span class="line"><span>否（有的是文件级，有的是函数级）→ 综合困难，先统一粒度</span></span></code></pre></div><h2 id="项目二-流水线编排" tabindex="-1">项目二：流水线编排 <a class="header-anchor" href="#项目二-流水线编排" aria-label="Permalink to &quot;项目二：流水线编排&quot;">​</a></h2><p>了解了并行探索的模式，我们再来看看流水线编排如何实现。</p><h3 id="bug修复流水线" tabindex="-1">Bug修复流水线 <a class="header-anchor" href="#bug修复流水线" aria-label="Permalink to &quot;Bug修复流水线&quot;">​</a></h3><p>实战项目位于 <code>03-SubAgents/projects/05-bugfix-pipeline/</code>，包含四个流水线子代理。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>05-bugfix-pipeline/</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── user-service.js # 用户服务（有 bug）</span></span>
<span class="line"><span>│ ├── cart-service.js # 购物车服务（有 bug）</span></span>
<span class="line"><span>│ ├── order-service.js # 订单服务（有 bug）</span></span>
<span class="line"><span>│ └── utils.js # 工具函数</span></span>
<span class="line"><span>├── tests/</span></span>
<span class="line"><span>│ └── services.test.js # 测试文件</span></span>
<span class="line"><span>└── .claude/agents/</span></span>
<span class="line"><span>├── bug-locator.md # 定位：找到问题在哪</span></span>
<span class="line"><span>├── bug-analyzer.md # 分析：理解为什么出问题</span></span>
<span class="line"><span>├── bug-fixer.md # 修复：实施修复</span></span>
<span class="line"><span>└── bug-verifier.md # 验证：确认修复有效</span></span></code></pre></div><p>这四个子代理，对应Bug修复流水线的四个阶段。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945070/ec07447b1c6fcf37cd15dd0f9670c562.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945070/ec07447b1c6fcf37cd15dd0f9670c562.jpg" alt=""></a></p><p>每个代理职责和角色清晰，每个节点都 <strong>可被单独替换 / 回滚 / 审计。</strong></p><ul><li><p>Locator：只回答“在哪”</p></li><li><p>Analyzer：只回答 “为什么”</p></li><li><p>Fixer：只负责 “怎么改”</p></li><li><p>Verifier：只负责 “改对没有”</p></li></ul><p>下面我们按“定位、分析、修复、验证”的分工顺序挨个拆解。</p><p><strong>阶段一：Locator（定位）</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: bug-locator</span></span>
<span class="line"><span>description: Locate the source of bugs in the codebase. First step in bug investigation.</span></span>
<span class="line"><span>tools: Read, Grep, Glob</span></span>
<span class="line"><span>model: sonnet</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are a bug investigation specialist focused on locating issues in code.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Your Role</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are the FIRST step in the bug fix pipeline. Your job is to:</span></span>
<span class="line"><span>1. Understand the bug symptoms</span></span>
<span class="line"><span>2. Find where the bug likely originates</span></span>
<span class="line"><span>3. Identify related code that might be affected</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## When Invoked</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. **Parse Bug Description**: Extract key information</span></span>
<span class="line"><span>   - Error messages</span></span>
<span class="line"><span>   - Stack traces</span></span>
<span class="line"><span>   - Symptoms/behavior</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. **Search Codebase**: Use Grep/Glob to find relevant code</span></span>
<span class="line"><span>   - Search for function names from stack traces</span></span>
<span class="line"><span>   - Search for error messages</span></span>
<span class="line"><span>   - Search for related keywords</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. **Narrow Down Location**: Identify the most likely source files</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Output Format</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`markdown</span></span>
<span class="line"><span>## Bug Location Report</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Symptoms</span></span>
<span class="line"><span>[Summary of reported issue]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Search Results</span></span>
<span class="line"><span>- Found [X] potentially related files</span></span>
<span class="line"><span>- Key matches: [list]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Most Likely Location</span></span>
<span class="line"><span>**File**: [path]</span></span>
<span class="line"><span>**Function**: [name]</span></span>
<span class="line"><span>**Line**: [approximate]</span></span>
<span class="line"><span>**Confidence**: High/Medium/Low</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Related Code</span></span>
<span class="line"><span>- [file]: [why related]</span></span>
<span class="line"><span>- [file]: [why related]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Handoff to Analyzer</span></span>
<span class="line"><span>[What the analyzer should focus on]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Guidelines</span></span>
<span class="line"><span>- Be thorough in searching - check multiple patterns</span></span>
<span class="line"><span>- Consider indirect causes (the bug might manifest in one place but originate elsewhere)</span></span>
<span class="line"><span>- Note any related code that might be affected by a fix</span></span>
<span class="line"><span>- DO NOT suggest fixes - that&#39;s for the fixer</span></span>
<span class="line"><span>- Keep output concise for the analyzer to continue</span></span></code></pre></div><p>设计关键点：</p><ul><li><p><code>model: sonnet</code> ：定位 bug 需要较强的推理能力</p></li><li><p>DO NOT suggest fixes：明确告诉它这不是它的职责</p></li><li><p>Handoff to Analyzer：为下一阶段准备信息</p></li></ul><p><strong>阶段二：Analyzer（分析）</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: bug-analyzer</span></span>
<span class="line"><span>description: Analyze root cause of bugs after location is identified. Second step in bug investigation.</span></span>
<span class="line"><span>tools: Read, Grep, Glob</span></span>
<span class="line"><span>model: sonnet</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are a bug analysis specialist focused on understanding root causes.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Your Role</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are the SECOND step in the bug fix pipeline. You receive:</span></span>
<span class="line"><span>- Bug location from the locator</span></span>
<span class="line"><span>- Symptoms description</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Your job is to:</span></span>
<span class="line"><span>1. Deeply understand WHY the bug occurs</span></span>
<span class="line"><span>2. Identify the root cause (not just the symptom)</span></span>
<span class="line"><span>3. Assess the impact and complexity</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## When Invoked</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. **Read Identified Code**: Carefully read the suspected location</span></span>
<span class="line"><span>2. **Trace Execution**: Understand the code flow</span></span>
<span class="line"><span>3. **Identify Root Cause**: Find the actual bug, not just symptoms</span></span>
<span class="line"><span>4. **Assess Impact**: What else might be affected?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Analysis Checklist</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- [ ] Data type issues (string vs number, null checks)</span></span>
<span class="line"><span>- [ ] Race conditions (concurrent access)</span></span>
<span class="line"><span>- [ ] Edge cases (empty arrays, zero values)</span></span>
<span class="line"><span>- [ ] Logic errors (wrong operators, missing conditions)</span></span>
<span class="line"><span>- [ ] Resource leaks (unclosed connections)</span></span>
<span class="line"><span>- [ ] Error handling gaps</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Output Format</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`markdown</span></span>
<span class="line"><span>## Bug Analysis Report</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Location Confirmed</span></span>
<span class="line"><span>**File**: [path]</span></span>
<span class="line"><span>**Function**: [name]</span></span>
<span class="line"><span>**Line(s)**: [range]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Root Cause</span></span>
<span class="line"><span>[Clear explanation of WHY the bug occurs]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Code Snippet</span></span>
<span class="line"><span>\`\`\`javascript</span></span>
<span class="line"><span>// The problematic code</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Bug Category</span></span>
<span class="line"><span>- [ ] Logic Error</span></span>
<span class="line"><span>- [ ] Type Error</span></span>
<span class="line"><span>- [ ] Race Condition</span></span>
<span class="line"><span>- [ ] Edge Case</span></span>
<span class="line"><span>- [ ] Resource Leak</span></span>
<span class="line"><span>- [ ] Other: [specify]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Impact Assessment</span></span>
<span class="line"><span>- **Severity**: Critical/High/Medium/Low</span></span>
<span class="line"><span>- **Scope**: [what&#39;s affected]</span></span>
<span class="line"><span>- **Data Impact**: [any data corruption risk?]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Fix Complexity</span></span>
<span class="line"><span>- **Estimated Effort**: Simple/Moderate/Complex</span></span>
<span class="line"><span>- **Risk of Regression**: Low/Medium/High</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Handoff to Fixer</span></span>
<span class="line"><span>**Recommended Approach**: [brief guidance]</span></span>
<span class="line"><span>**Watch Out For**: [potential pitfalls]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Guidelines</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Focus on the ROOT cause, not symptoms</span></span>
<span class="line"><span>- Consider if this is a pattern that might exist elsewhere</span></span>
<span class="line"><span>- Assess whether the fix could break other things</span></span>
<span class="line"><span>- DO NOT implement fixes - just analyze</span></span></code></pre></div><p>类似 Locator，但关注点是“为什么”而不是“在哪”，而是分析代码逻辑、找出根本原因并提出修复方向。</p><p><strong>阶段三：Fixer（修复）</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: bug-fixer</span></span>
<span class="line"><span>description: Implement bug fixes after analysis is complete. Third step in bug fix pipeline.</span></span>
<span class="line"><span>tools: Read, Edit, Write, Grep, Glob</span></span>
<span class="line"><span>model: sonnet</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are a bug fix specialist focused on implementing correct and safe fixes.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Your Role</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are the THIRD step in the bug fix pipeline. You receive:</span></span>
<span class="line"><span>- Root cause analysis</span></span>
<span class="line"><span>- Recommended approach</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Your job is to:</span></span>
<span class="line"><span>1. Implement the fix correctly</span></span>
<span class="line"><span>2. Ensure the fix doesn&#39;t break other things</span></span>
<span class="line"><span>3. Follow code style conventions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Fix Principles</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Do</span></span>
<span class="line"><span>- Make the MINIMAL change needed</span></span>
<span class="line"><span>- Match existing code style</span></span>
<span class="line"><span>- Add necessary null/type checks</span></span>
<span class="line"><span>- Use existing utility functions when available</span></span>
<span class="line"><span>- Add inline comments for non-obvious fixes</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Don&#39;t</span></span>
<span class="line"><span>- Refactor unrelated code</span></span>
<span class="line"><span>- Add unnecessary abstractions</span></span>
<span class="line"><span>- Change function signatures without reason</span></span>
<span class="line"><span>- Remove existing functionality</span></span>
<span class="line"><span>- Over-engineer the solution</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Output Format</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`markdown</span></span>
<span class="line"><span>## Bug Fix Report</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Changes Made</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**File**: [path]</span></span>
<span class="line"><span>**Type**: Modified/Added/Removed</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`diff</span></span>
<span class="line"><span>- old code</span></span>
<span class="line"><span>+ new code</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Fix Explanation</span></span>
<span class="line"><span>[Why this fix works]</span></span>
<span class="line"><span>### Potential Side Effects</span></span>
<span class="line"><span>[Any code that might be affected]</span></span>
<span class="line"><span>### Testing Notes</span></span>
<span class="line"><span>[What the verifier should check]</span></span>
<span class="line"><span>### Rollback Plan</span></span>
<span class="line"><span>[How to revert if needed]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Guidelines</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Keep fixes focused and minimal</span></span>
<span class="line"><span>- If uncertain, err on the side of safety</span></span>
<span class="line"><span>- Don&#39;t change more than necessary</span></span>
<span class="line"><span>- Ensure backward compatibility when possible</span></span>
<span class="line"><span>- Hand off to verifier with clear testing notes</span></span></code></pre></div><p>设计关键点如下。</p><ul><li><p><code>tools: Read, Edit, Write</code> ：有这个阶段有写权限</p></li><li><p>Make the MINIMAL change needed：防止过度修改</p></li><li><p>Rollback Plan：考虑回滚方案</p></li></ul><p><strong>阶段四：Verifier（验证）</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: bug-verifier</span></span>
<span class="line"><span>description: Verify bug fixes by running tests. Final step in bug fix pipeline.</span></span>
<span class="line"><span>tools: Read, Bash, Grep, Glob</span></span>
<span class="line"><span>model: haiku</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are a QA specialist focused on verifying bug fixes.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Your Role</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are the FINAL step in the bug fix pipeline. You receive:</span></span>
<span class="line"><span>- The fix that was implemented</span></span>
<span class="line"><span>- Testing notes from the fixer</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Your job is to:</span></span>
<span class="line"><span>1. Run existing tests</span></span>
<span class="line"><span>2. Verify the fix works</span></span>
<span class="line"><span>3. Check for regressions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## When Invoked</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. **Run Tests**: Execute the test suite</span></span>
<span class="line"><span>2. **Analyze Results**: Check pass/fail status</span></span>
<span class="line"><span>3. **Verify Fix**: Confirm the original bug is fixed</span></span>
<span class="line"><span>4. **Check Regressions**: Ensure nothing else broke</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Verification Checklist</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- [ ] All existing tests pass</span></span>
<span class="line"><span>- [ ] The specific bug scenario is fixed</span></span>
<span class="line"><span>- [ ] No new errors introduced</span></span>
<span class="line"><span>- [ ] Code changes match what was intended</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Output Format</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`markdown</span></span>
<span class="line"><span>## Verification Report</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Test Results</span></span>
<span class="line"><span>**Status**: PASS / FAIL</span></span>
<span class="line"><span>**Total Tests**: X</span></span>
<span class="line"><span>**Passed**: X</span></span>
<span class="line"><span>**Failed**: X</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Bug Fix Verification</span></span>
<span class="line"><span>**Original Bug**: [description]</span></span>
<span class="line"><span>**Status**: FIXED / NOT FIXED / PARTIALLY FIXED</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Regression Check</span></span>
<span class="line"><span>**New Issues Found**: Yes / No</span></span>
<span class="line"><span>- [If yes, list them]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Final Verdict</span></span>
<span class="line"><span>- [ ] Safe to merge</span></span>
<span class="line"><span>- [ ] Needs more work: [reason]</span></span>
<span class="line"><span>- [ ] Needs manual testing: [what to test]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Notes for Human Review</span></span>
<span class="line"><span>[Any observations or concerns]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Commands to Run</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`bash</span></span>
<span class="line"><span># Check for syntax errors</span></span>
<span class="line"><span>node --check [file]</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Run tests</span></span>
<span class="line"><span>npm test</span></span>
<span class="line"><span># or</span></span>
<span class="line"><span>node tests/[test-file].js</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Guidelines</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Run ALL tests, not just related ones</span></span>
<span class="line"><span>- Report any warnings, not just errors</span></span>
<span class="line"><span>- Be honest about test coverage gaps</span></span>
<span class="line"><span>- Suggest manual testing if needed</span></span>
<span class="line"><span>- Provide clear pass/fail verdict</span></span></code></pre></div><p>设计关键点如下。</p><ul><li><code>tools: Read, Bash, Grep</code> ：可以执行测试</li><li>运行测试验证修复</li><li>检查是否引入新问题</li></ul><h3 id="使用流水线" tabindex="-1">使用流水线 <a class="header-anchor" href="#使用流水线" aria-label="Permalink to &quot;使用流水线&quot;">​</a></h3><p>完成前面的编排，我们体验一下流水线的使用效果。进入项目目录，描述 bug：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我有一个 bug：用户登录后偶尔会 token 验证失败。</span></span>
<span class="line"><span>帮我用流水线方式修复：</span></span>
<span class="line"><span>1. 先让 bug-locator 找到相关代码</span></span>
<span class="line"><span>2. 让 bug-analyzer 分析原因</span></span>
<span class="line"><span>3. 让 bug-fixer 修复</span></span>
<span class="line"><span>4. 让 bug-verifier 跑测试验证</span></span></code></pre></div><p>你会看到四个子代理依次执行，每个阶段返回简洁的报告，主对话保持清洁。对于复杂 bug、需要系统性排查的情况，流水线尤其有价值。而且每个子代理职责清晰，便于追踪问题；且权限递进，只有必要时才给写权限。</p><p>流水线的另一个优势是 <strong>可中断性</strong>。比如：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Locator：找到了 3 个可能的位置</span></span>
<span class="line"><span>你：等等，第二个位置不太可能，那是测试代码</span></span>
<span class="line"><span>Locator：好的，聚焦到第一和第三个位置...</span></span></code></pre></div><p>你可以在任何阶段介入，修正方向，而不用等整个流程跑完才发现问题。</p><h3 id="流水线的架构约束-子代理不能嵌套" tabindex="-1">流水线的架构约束：子代理不能嵌套 <a class="header-anchor" href="#流水线的架构约束-子代理不能嵌套" aria-label="Permalink to &quot;流水线的架构约束：子代理不能嵌套&quot;">​</a></h3><p>在设计流水线之前，有一个关键约束必须了解： <strong>子代理不能生成子代理</strong>。也就是说，Locator 不能自己去调用 Analyzer，Analyzer 也不能自己去调用 Fixer。</p><p>这意味着什么？ <strong>流水线的编排者只能是主对话</strong>。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>错误的想象：</span></span>
<span class="line"><span>Locator 自动调用 Analyzer → Analyzer 自动调用 Fixer → Fixer 自动调用 Verifier</span></span>
<span class="line"><span>（这在 Claude Code 中做不到）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>实际的架构：</span></span>
<span class="line"><span>主对话 → 调用 Locator → 收到结果 → 调用 Analyzer → 收到结果 → 调用 Fixer → 收到结果 → 调用 Verifier</span></span>
<span class="line"><span>（每一步都经过主对话）</span></span></code></pre></div><p>这个约束其实是一个好的设计，原因有三个。</p><ol><li><p>主对话始终拥有全局视野：它看到了每个阶段的输出，可以在任何节点做出判断——继续、重试还是中止。</p></li><li><p>权限边界天然隔离：每个子代理只有自己配置的工具权限，不可能通过嵌套调用绕过限制。</p></li><li><p>调试更容易：出了问题，你知道每个阶段的输入输出分别是什么，不会出现“子代理 A 调了子代理 B，B 又调了 C，结果在 C 里出了错但你只看到 A 的输出”这种黑盒嵌套。</p></li></ol><p>因此，你在写流水线子代理的 prompt 时，不要写“完成后调用 bug-analyzer 继续分析”。这样的指令子代理做不到。正确的做法是让子代理专注于自己的阶段，把输出格式设计好（交接契约），由主对话负责串接。</p><h3 id="长流水线的保障-resume-恢复机制" tabindex="-1">长流水线的保障：Resume 恢复机制 <a class="header-anchor" href="#长流水线的保障-resume-恢复机制" aria-label="Permalink to &quot;长流水线的保障：Resume 恢复机制&quot;">​</a></h3><p>流水线越长，中途被打断的风险就越大——网络断了、终端关了，甚至只是你关上电脑去吃了个午饭。</p><p>因此 Claude Code 提供了 <strong>Resume 机制</strong>，每个子代理执行完后都有一个 agent ID，你可以用这个 ID 恢复它的完整上下文。对于流水线来说，这意味着，如果四阶段流水线跑到第三阶段时你的服务器重启了，你只需要：</p><ol><li><p>重新打开 Claude Code。</p></li><li><p>Locator 和 Analyzer 的结果已经在主对话历史中（如果你用了–resume）。</p></li><li><p>Fixer 中途断了？用 <code>claude --resume</code> 命令恢复 Fixer 的上下文，让它继续。</p></li><li><p>或者直接用 Analyzer 之前的输出，重新触发 Fixer 从头开始。</p></li></ol><p>在恢复的会话中，主对话记得之前每个阶段的结果，你可以直接说：“继续，从 Fixer 阶段重新开始”。</p><p>Resume 的工程价值在长流水线中尤为突出。</p><ul><li>不怕中断：任何阶段断了都可以恢复。</li><li>支持跨时段工作：今天跑完 Locator + Analyzer，明天接着跑 Fixer + Verifier。</li><li>审批可以异步：Analyzer 跑完后你不需要立刻审批，关机走人，第二天 resume 回来继续。</li></ul><h2 id="流水线的核心工程问题-阶段间的-交接契约" tabindex="-1">流水线的核心工程问题：阶段间的“交接契约” <a class="header-anchor" href="#流水线的核心工程问题-阶段间的-交接契约" aria-label="Permalink to &quot;流水线的核心工程问题：阶段间的“交接契约”&quot;">​</a></h2><p>到目前为止，我们看到了流水线的骨架——四个阶段能够各司其职。但在实际使用中，流水线最容易出问题的不是每个阶段本身，而是 <strong>阶段之间的信息传递</strong>。你可能已经意识到了，这里的所谓交接，就是我们在 <a href="https://time.geekbang.org/column/article/943942" target="_blank" rel="noreferrer">第 4 讲</a>“量体裁衣”中所介绍的 <strong>Handoffs模式</strong> 的应用。</p><h3 id="什么是-交接契约" tabindex="-1">什么是“交接契约”？ <a class="header-anchor" href="#什么是-交接契约" aria-label="Permalink to &quot;什么是“交接契约”？&quot;">​</a></h3><p>流水线中，前一个子代理的输出就是后一个子代理的输入（通过主对话转发）。如果前一个阶段输出的信息不完整或格式不对，后一个阶段就会“瞎干”。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果Locator 输出：&quot;bug 可能在 auth 模块里。&quot;</span></span>
<span class="line"><span>                    ↓</span></span>
<span class="line"><span>Analyzer 收到这句话后：&quot;auth 模块？哪个文件？哪个函数？我该分析什么？&quot;</span></span>
<span class="line"><span>                    ↓</span></span>
<span class="line"><span>结果：Analyzer 自己又做了一遍 Locator 的工作，流水线形同虚设。</span></span></code></pre></div><p>因此，在每个阶段的输出格式中，应该有一个明确的 <strong>Handoff（交接）</strong> 部分，告诉下一阶段“你需要关注什么”。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## Locator → Analyzer 的交接契约</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Locator 必须提供：</span></span>
<span class="line"><span>1. 具体文件路径（不是&quot;大概在某模块&quot;）</span></span>
<span class="line"><span>2. 具体函数/方法名</span></span>
<span class="line"><span>3. 嫌疑代码行号范围</span></span>
<span class="line"><span>4. 为什么怀疑这里（搜索证据）</span></span>
<span class="line"><span>5. 相关联的其他文件列表</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Analyzer 期望收到：</span></span>
<span class="line"><span>1. 明确的调查范围（文件+函数）</span></span>
<span class="line"><span>2. 症状描述（用户看到什么）</span></span>
<span class="line"><span>3. 已排除的可能性（Locator 搜索过但排除的位置）</span></span>
<span class="line"><span>## Analyzer → Fixer 的交接契约</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Analyzer 必须提供：</span></span>
<span class="line"><span>1. 根因定位（一句话）</span></span>
<span class="line"><span>2. 修复方向建议（不超过 3 个方案）</span></span>
<span class="line"><span>3. 推荐方案及理由</span></span>
<span class="line"><span>4. 修改涉及的文件列表</span></span>
<span class="line"><span>5. 需要注意的边界条件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Fixer 期望收到：</span></span>
<span class="line"><span>1. 明确的&quot;改什么&quot;（文件+位置+原因）</span></span>
<span class="line"><span>2. 明确的&quot;怎么改&quot;（方向，不需要具体代码）</span></span>
<span class="line"><span>3. 明确的&quot;别碰什么&quot;（不应该修改的部分）</span></span>
<span class="line"><span>## Fixer → Verifier 的交接契约</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Fixer 必须提供：</span></span>
<span class="line"><span>1. 改了哪些文件（diff 格式）</span></span>
<span class="line"><span>2. 为什么这么改</span></span>
<span class="line"><span>3. 可能的副作用清单</span></span>
<span class="line"><span>4. 需要运行的测试命令</span></span>
<span class="line"><span>5. 验证通过的标准是什么</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Verifier 期望收到：</span></span>
<span class="line"><span>1. 变更清单（知道要验证什么）</span></span>
<span class="line"><span>2. 测试命令（知道怎么验证）</span></span>
<span class="line"><span>3. 预期结果（知道什么算通过）</span></span></code></pre></div><h3 id="在-prompt-中实现交接契约" tabindex="-1">在 prompt 中实现交接契约 <a class="header-anchor" href="#在-prompt-中实现交接契约" aria-label="Permalink to &quot;在 prompt 中实现交接契约&quot;">​</a></h3><p>回看 Locator 的配置，它的输出格式中有：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>### Handoff to Analyzer</span></span>
<span class="line"><span>[What the analyzer should focus on]</span></span></code></pre></div><p>这一段就是交接契约的实现。但原始版本太模糊了——“What the analyzer should focus on”没有约束输出什么。</p><p>我们可以这样改进一下原始版本。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>### Handoff to Analyzer</span></span>
<span class="line"><span>- **Primary suspect**: [file:function:line_range]</span></span>
<span class="line"><span>- **Symptoms to reproduce**: [具体步骤]</span></span>
<span class="line"><span>- **Hypothesis**: [为什么怀疑这里]</span></span>
<span class="line"><span>- **Already excluded**: [搜索过但排除的位置及原因]</span></span>
<span class="line"><span>- **Related files to check**: [可能受影响的其他文件]</span></span></code></pre></div><p>此处需要遵循的经验法则是——交接时信息量要充足，让下一阶段 <strong>无需重复上一阶段的工作</strong>。如果 Analyzer 收到 Locator 的输出后，还需要自己 Grep 一遍才能开始分析，说明交接契约设计不合格。</p><h2 id="主对话的角色-编排者-而非旁观者" tabindex="-1">主对话的角色：编排者，而非旁观者 <a class="header-anchor" href="#主对话的角色-编排者-而非旁观者" aria-label="Permalink to &quot;主对话的角色：编排者，而非旁观者&quot;">​</a></h2><p>在 Claude Code 中，流水线不是一个“启动后自动跑完”的系统。 <strong>主对话就是编排者</strong>——它负责触发每个阶段、审查每个阶段的输出，决定是否继续、重试或中止、同时在阶段之间注入人工判断。</p><h3 id="编排者的四种介入形式" tabindex="-1">编排者的四种介入形式 <a class="header-anchor" href="#编排者的四种介入形式" aria-label="Permalink to &quot;编排者的四种介入形式&quot;">​</a></h3><p>编排者有全自动、关键阶段审批、逐阶段审批和回退重试四种介入形式。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>形式一：全自动（信任度高）</span></span>
<span class="line"><span>┌─────────┐  自动  ┌─────────┐  自动  ┌─────────┐  自动  ┌─────────┐</span></span>
<span class="line"><span>│ Locator │ ────→ │ Analyzer│ ────→ │  Fixer  │ ────→ │Verifier │</span></span>
<span class="line"><span>└─────────┘       └─────────┘       └─────────┘       └─────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>形式二：关键阶段审批（推荐）</span></span>
<span class="line"><span>┌─────────┐  自动  ┌─────────┐       ┌─────────┐  自动  ┌─────────┐</span></span>
<span class="line"><span>│ Locator │ ────→ │ Analyzer│ ─?──→ │  Fixer  │ ────→ │Verifier │</span></span>
<span class="line"><span>└─────────┘       └─────────┘  ↑    └─────────┘       └─────────┘</span></span>
<span class="line"><span>                            人工审批</span></span>
<span class="line"><span>                        &quot;这个根因分析对吗？</span></span>
<span class="line"><span>                         确认后再让它改代码&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>形式三：逐阶段审批（谨慎）</span></span>
<span class="line"><span>┌─────────┐       ┌─────────┐       ┌─────────┐       ┌─────────┐</span></span>
<span class="line"><span>│ Locator │ ─?──→ │ Analyzer│ ─?──→ │  Fixer  │ ─?──→ │Verifier │</span></span>
<span class="line"><span>└─────────┘  ↑    └─────────┘  ↑    └─────────┘  ↑    └─────────┘</span></span>
<span class="line"><span>          人工审批           人工审批           人工审批</span></span>
<span class="line"><span></span></span>
<span class="line"><span>形式四：回退重试（遇到问题时）</span></span>
<span class="line"><span>┌─────────┐       ┌─────────┐       ┌─────────┐</span></span>
<span class="line"><span>│ Locator │ ────→ │ Analyzer│ ────→ │  Fixer  │</span></span>
<span class="line"><span>└─────────┘       └─────────┘       └────┬────┘</span></span>
<span class="line"><span>                       ↑                  │</span></span>
<span class="line"><span>                       └──────────────────┘</span></span>
<span class="line"><span>                      &quot;修复方向不对，</span></span>
<span class="line"><span>                       回退到分析阶段&quot;</span></span></code></pre></div><p>就Bug修复这个具体问题而言，并不是每个阶段都需要人工审批，但有一个关键决策点必须把关：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Analyzer → Fixer</span></span>
<span class="line"><span> ↑</span></span>
<span class="line"><span>这个位置最关键！</span></span></code></pre></div><p>为什么？因为这是从 <strong>只读到读写</strong> 的跨越——一旦 Fixer 开始修改代码，回退成本就高了。在这个位置审查 Analyzer 的根因分析，确认方向正确后再继续，是性价比最高的介入方式。</p><h3 id="编排者的-prompt-设计" tabindex="-1">编排者的 prompt 设计 <a class="header-anchor" href="#编排者的-prompt-设计" aria-label="Permalink to &quot;编排者的 prompt 设计&quot;">​</a></h3><p>你可以在触发流水线时明确编排方式：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我修复这个 bug：用户登录后偶尔 token 验证失败。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>执行方式：</span></span>
<span class="line"><span>1. 先让 bug-locator 定位 → 自动传给 bug-analyzer</span></span>
<span class="line"><span>2. bug-analyzer 分析完后 → 先给我看根因分析，我确认后再继续</span></span>
<span class="line"><span>3. 我确认后 → 让 bug-fixer 修复 → 自动传给 bug-verifier</span></span>
<span class="line"><span>4. bug-verifier 验证完给我最终报告</span></span></code></pre></div><p>这就是形式二：关键阶段审批的实际使用方式。</p><h2 id="当流水线阶段失败时怎么办" tabindex="-1">当流水线阶段失败时怎么办？ <a class="header-anchor" href="#当流水线阶段失败时怎么办" aria-label="Permalink to &quot;当流水线阶段失败时怎么办？&quot;">​</a></h2><p>真实使用中，流水线不总是顺利的。每个阶段都可能失败，需要不同的处理策略：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945070/28yy3c8646f021bfe863791b5002b9da.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945070/28yy3c8646f021bfe863791b5002b9da.jpg" alt=""></a></p><p>死循环是流水线设计中一个常见陷阱，避免死循环的一个关键原则是——Verifier 失败时不要让 Fixer “再试一次”。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>错误做法：</span></span>
<span class="line"><span>Verifier 说测试失败 → 让 Fixer 再改一次 → Verifier 又失败 → 再改...</span></span>
<span class="line"><span>（进入死循环，Fixer 在瞎猜）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>正确做法：</span></span>
<span class="line"><span>Verifier 说测试失败 → 回退到 Analyzer</span></span>
<span class="line"><span>  → Analyzer 结合 Fixer 的修改和 Verifier 的失败信息重新分析</span></span>
<span class="line"><span>  → 可能发现根因判断有误</span></span>
<span class="line"><span>  → 给出新的修复方向</span></span>
<span class="line"><span>  → Fixer 基于新分析修复</span></span></code></pre></div><p>这是因为Verifier 的失败信息是 <strong>新的证据</strong>，应该反馈给 Analyzer 而不是 Fixer。Fixer 只负责执行，不负责判断方向。</p><p>在实际使用中，建议设定一个心理上的重试上限。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同一阶段重试超过 2 次 → 停下来重新审视问题</span></span>
<span class="line"><span>整个流水线回退超过 1 次 → 可能需要人工介入深度分析</span></span></code></pre></div><p>如果 AI 在反复循环但没有进展，这时你需要考虑以下原因。</p><ol><li>问题比预想的复杂，需要更多上下文</li><li>问题的根因不在当前代码中（可能是配置、环境、数据问题）</li><li>子代理的 prompt 对这类问题的覆盖不够</li></ol><h2 id="并行-vs-流水线-什么时候用什么" tabindex="-1">并行 vs 流水线：什么时候用什么 <a class="header-anchor" href="#并行-vs-流水线-什么时候用什么" aria-label="Permalink to &quot;并行 vs 流水线：什么时候用什么&quot;">​</a></h2><p>至此，我们已经全面了解了并行和流水线这两种子代理模式，在一个特定场景中，核心判断标准是：</p><ul><li><p>任务之间 <strong>独立</strong> 吗？→ 并行</p></li><li><p>任务之间有 <strong>依赖</strong> 吗？→ 流水线</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945070/4217eb94383a247c592ca6141d9186aa.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945070/4217eb94383a247c592ca6141d9186aa.jpg" alt=""></a></p><p>真实工程任务很少是纯并行或纯流水线。更常见的是 <strong>混合模式</strong>——一部分任务并行，一部分串行。</p><h3 id="模式一-fan-out-→-fan-in-扇出→聚合" tabindex="-1">模式一：Fan-out → Fan-in（扇出→聚合） <a class="header-anchor" href="#模式一-fan-out-→-fan-in-扇出→聚合" aria-label="Permalink to &quot;模式一：Fan-out → Fan-in（扇出→聚合）&quot;">​</a></h3><p><strong>典型场景</strong>：接手新项目时，先并行探索各模块，再综合分析。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌─── Explorer A ───┐</span></span>
<span class="line"><span>                    │                   │</span></span>
<span class="line"><span>Input ──→ Split ──→├─── Explorer B ───├──→ Synthesizer ──→ Output</span></span>
<span class="line"><span>                    │                   │</span></span>
<span class="line"><span>                    └─── Explorer C ───┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        串行              并行              串行</span></span></code></pre></div><p><strong>prompt</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我理解这个项目的架构：</span></span>
<span class="line"><span>1. 同时让 auth-explorer、db-explorer、api-explorer 各自探索</span></span>
<span class="line"><span>2. 收到三份报告后，综合分析模块间的依赖关系和数据流</span></span></code></pre></div><p>主对话在这里充当了Split 和 Synthesize的角色——它拆分任务、分发给子代理、收集结果、综合分析。</p><h3 id="模式二-pipeline-parallel-stage-流水线中嵌套并行" tabindex="-1">模式二：Pipeline + Parallel Stage（流水线中嵌套并行） <a class="header-anchor" href="#模式二-pipeline-parallel-stage-流水线中嵌套并行" aria-label="Permalink to &quot;模式二：Pipeline + Parallel Stage（流水线中嵌套并行）&quot;">​</a></h3><p><strong>典型场景</strong>：定位到问题位置后，需要从多个维度分析（安全性、性能、兼容性），再综合决定修复方案。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────┐     ┌───────────────────────┐     ┌──────────┐</span></span>
<span class="line"><span>│          │     │    ┌─── Check A ───┐  │     │          │</span></span>
<span class="line"><span>│ Locator  │ ──→ │    ├─── Check B ───├  │ ──→ │  Fixer   │</span></span>
<span class="line"><span>│          │     │    └─── Check C ───┘  │     │          │</span></span>
<span class="line"><span>└──────────┘     │     并行检查多维度     │     └──────────┘</span></span>
<span class="line"><span>                 └───────────────────────┘</span></span>
<span class="line"><span>    串行                  并行                    串行</span></span></code></pre></div><p><strong>prompt</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bug-locator 已经定位到 user-service.js 的 validateToken 函数。现在：</span></span>
<span class="line"><span>1. 同时从三个角度分析这个函数：</span></span>
<span class="line"><span>   - 安全性（有没有漏洞）</span></span>
<span class="line"><span>   - 性能（有没有阻塞）</span></span>
<span class="line"><span>   - 兼容性（改了会不会影响调用方）</span></span>
<span class="line"><span>2. 综合三份分析，决定修复方案</span></span>
<span class="line"><span>3. 让 bug-fixer 执行修复</span></span></code></pre></div><h3 id="模式三-parallel-pipelines-多条流水线并行" tabindex="-1">模式三：Parallel Pipelines（多条流水线并行） <a class="header-anchor" href="#模式三-parallel-pipelines-多条流水线并行" aria-label="Permalink to &quot;模式三：Parallel Pipelines（多条流水线并行）&quot;">​</a></h3><p><strong>典型场景</strong>：同时修复多个互不相关的 bug。每个 bug 走独立的流水线，最后统一做集成测试。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pipeline 1: Locator A → Analyzer A → Fixer A</span></span>
<span class="line"><span>                                                  ──→ Integration Test</span></span>
<span class="line"><span>Pipeline 2: Locator B → Analyzer B → Fixer B</span></span></code></pre></div><p>这里给出选择混合模式的判断树。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的任务有多个子任务吗？</span></span>
<span class="line"><span>├── 否 → 不需要混合，用单个子代理或简单流水线</span></span>
<span class="line"><span>└── 是 → 子任务之间有依赖关系吗？</span></span>
<span class="line"><span>    ├── 全部独立 → 纯并行</span></span>
<span class="line"><span>    ├── 全部依赖 → 纯流水线</span></span>
<span class="line"><span>    └── 部分独立、部分依赖 → 混合模式</span></span>
<span class="line"><span>        ├── 先并行收集，再串行综合 → Fan-out → Fan-in</span></span>
<span class="line"><span>        ├── 串行流程中某一步需要多角度 → Pipeline + Parallel Stage</span></span>
<span class="line"><span>        └── 多个独立的串行流程 → Parallel Pipelines</span></span></code></pre></div><h2 id="本讲小结" tabindex="-1">本讲小结 <a class="header-anchor" href="#本讲小结" aria-label="Permalink to &quot;本讲小结&quot;">​</a></h2><p>今天我们学习了子代理的两个高级模式。</p><ul><li><p><strong>并行探索</strong> 支持多个子代理同时工作，适合独立任务的同时处理，提供快速 + 清洁的上下文，其核心价值是 <strong>速度</strong> + <strong>独立性。</strong></p></li><li><p><strong>流水线编排</strong> 支持多个子代理顺序工作，适合有依赖关系的连续阶段，子代理之间职责清晰 + 权限递进，其核心价值是 <strong>清晰度</strong> + <strong>可控性。</strong></p></li></ul><p>总结一下并行探索的设计原则。</p><ol><li><p>明确边界：每个子代理只关注自己的领域。</p></li><li><p>统一格式：所有子代理输出格式一致，便于综合。</p></li><li><p>用快模型：探索任务用 <code>haiku</code> 更高效。</p></li><li><p>只读权限：探索不需要修改任何东西。</p></li><li><p>验证独立性：并行前检查子任务是否真正独立——如果存在信息依赖，要么改为串行，要么在综合阶段补充跨模块分析。</p></li></ol><p>流水线的设计原则如下。</p><ol><li><p>职责分离：每个阶段只做一件事。</p></li><li><p>权限递进：只在必要时给写权限。</p></li><li><p>清晰交接：每个阶段为下一阶段准备信息。</p></li><li><p>可中断：允许人工介入任何阶段。</p></li><li><p>可回滚：修复阶段要考虑回滚方案。</p></li><li><p>交接契约化：每个阶段的 Handoff 部分应该有明确的字段约束，而不是一句模糊的“告诉下一阶段该关注什么”。</p></li><li><p>失败回退到分析，而非重试执行：Verifier 失败时，回到 Analyzer 而不是让 Fixer “再试一次”。</p></li><li><p>在读写跨越点设置人工审批：Analyzer → Fixer 是流水线中成本最高的决策点，推荐在此处设置审批。</p></li></ol><p>在工程层面，并行探索的隐含前提是任务 <strong>真正独立</strong>——跨模块关联需要主对话在综合阶段补充分析。</p><p>流水线的核心不是简单分成多个阶段，而是 <strong>阶段间的交接契约</strong> 设计——信息必须完整传递，不能让下游重复上游的工作。主对话不是旁观者，而是 <strong>编排者</strong>——它负责审查、决策、介入和回退。流水线失败时，回退到分析阶段而非重试执行阶段——这是避免死循环的关键。</p><p>真实任务通常是 <strong>混合模式</strong>——需要掌握 Fan-out→Fan-in、Pipeline+Parallel Stage、Parallel Pipelines 三种混合模式的判断标准。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>你的项目中有没有适合并行探索的场景？比如需要同时理解多个模块的情况？</p></li><li><p>除了 bug 修复，还有哪些任务适合用流水线模式？比如代码迁移、功能开发等。</p></li><li><p>如果一个任务既有并行部分又有串行部分，你会怎么设计子代理的组合？</p></li><li><p>为以下流水线设计交接契约——需求文档 → 技术方案 → 代码实现 → 测试验证。每个阶段的 Handoff 应该包含哪些字段？</p></li><li><p>假设你的 bug-fixer 修复后，bug-verifier 跑测试发现原来的 bug 没修好，但引入了一个新的测试失败。你作为编排者应该怎么操作？写出具体的指令。</p></li></ol><h2 id="动手练习" tabindex="-1">动手练习 <a class="header-anchor" href="#动手练习" aria-label="Permalink to &quot;动手练习&quot;">​</a></h2><p><strong>练习一：并行探索</strong></p><ol><li><p>进入 <code>projects/04-parallel-explore/</code> 目录</p></li><li><p>运行 <code>同时让三个 explorer 探索各自模块，汇总成整体架构理解</code></p></li><li><p>观察三份报告和最终综合结果</p></li></ol><p><strong>练习二：流水线编排</strong></p><ol><li><p>进入 <code>projects/05-bugfix-pipeline/</code> 目录</p></li><li><p>用流水线方式修复其中一个 bug</p></li><li><p>在中间阶段试着介入，看看如何影响后续阶段</p></li></ol><p><strong>练习三：交接契约验证</strong></p><ol><li><p>在练习二中，当 Locator 完成后，阅读它的 Handoff 部分。</p></li><li><p>判断：如果你是 Analyzer，这些信息够不够你开始分析？缺什么？</p></li><li><p>修改 Locator 的 prompt，让 Handoff 部分更完整，重新跑一次，对比差异。</p></li></ol><p><strong>练习四：混合模式实操</strong></p><ol><li><p>用 Fan-out → Fan-in 模式理解项目：同时让三个 explorer 探索，然后综合分析。</p></li><li><p>基于综合分析中发现的问题，切换到流水线模式修复其中一个。</p></li><li><p>思考：哪些步骤你做了人工介入？哪些步骤你让它自动继续了？为什么？</p></li></ol><p>按照原定计划下一讲我们将进入新的主题： <strong>Skills 技能系统</strong>。不过，Claude在2026年2月6日最新推出的“ <a href="https://code.claude.com/docs/en/agent-teams" target="_blank" rel="noreferrer">团队协作</a>”（Agent Teams）功能很明显更适合整合进入SubAgent专题，因此佳哥正在积极创作相关内容，期待周五和大家见面。</p><p>欢迎你在留言区和我交流讨论。如果这一讲对你有启发，别忘了分享给身边更多朋友。</p>`,178)])])}const g=n(l,[["render",i]]);export{h as __pageData,g as default};
